CREATE OR REPLACE FUNCTION hacklab.demand_assignee_coherent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if new.assigned_user_id is null or new.status in ('COMPLETED', 'RESOLVED') then
        return new;
    end if;

    if not exists (
        select 1 from users u
        where u.id = new.assigned_user_id
          and u.status = 'ACTIVE'
          and u.sector_id = new.responsible_sector_id
    ) then
        raise exception '%: responsável individual precisa ser usuário ativo do setor responsável', tg_table_name
            using errcode = 'check_violation';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION hacklab.evaluation_scores_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    eval_status text;
    crit record;
begin
    select status into eval_status from evaluations
        where id = case when tg_op = 'DELETE' then old.evaluation_id else new.evaluation_id end;

    if eval_status = 'SUBMITTED' then
        raise exception 'evaluation_scores: avaliação enviada não tem notas alteradas'
            using errcode = 'check_violation';
    end if;

    if tg_op = 'DELETE' then
        return old;
    end if;

    select min_score, max_score into crit from evaluation_criteria where id = new.criterion_id;

    if new.score < crit.min_score or new.score > crit.max_score then
        raise exception 'evaluation_scores: nota % fora da faixa do critério (% a %)', new.score, crit.min_score, crit.max_score
            using errcode = 'check_violation';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION hacklab.evaluations_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if new.juror_id <> old.juror_id or new.team_id <> old.team_id or new.event_id <> old.event_id then
        raise exception 'evaluations: jurado, equipe e evento não mudam'
            using errcode = 'check_violation';
    end if;

    if old.status = 'SUBMITTED' and new.status = 'DRAFT' then
        raise exception 'evaluations: avaliação enviada não volta para rascunho (use a revisão)'
            using errcode = 'check_violation';
    end if;

    if old.status = 'SUBMITTED' and new.status = 'SUBMITTED' and new.comments is distinct from old.comments then
        raise exception 'evaluations: avaliação enviada não tem comentário alterado'
            using errcode = 'check_violation';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION hacklab.next_reference(prefix text, seq text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
    n bigint;
begin
    n := nextval(seq::regclass);
    -- Pelo menos 4 dígitos, sem truncar acima de 9999 (PEN-10000).
    return prefix || '-' || lpad(n::text, greatest(4, length(n::text)), '0');
end;
$function$

CREATE OR REPLACE FUNCTION hacklab.public_votes_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    session_status text;
begin
    if tg_op <> 'INSERT' then
        raise exception 'public_votes: voto é definitivo (sem UPDATE/DELETE)'
            using errcode = 'check_violation';
    end if;

    select status into session_status from voting_sessions where id = new.voting_session_id for share;

    if session_status is distinct from 'OPEN' then
        raise exception 'public_votes: sessão % não recebe votos', session_status
            using errcode = 'check_violation';
    end if;

    if not exists (
        select 1 from users u join roles r on r.id = u.role_id
        where u.id = new.user_id and u.status = 'ACTIVE' and r.code = 'VOTER'
    ) then
        raise exception 'public_votes: só usuário ACTIVE com perfil VOTER vota'
            using errcode = 'check_violation';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION hacklab.result_publications_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if tg_op = 'DELETE' then
        raise exception 'result_publications: publicação é histórica (revogue, não apague)'
            using errcode = 'check_violation';
    end if;

    if tg_op = 'INSERT' then
        if not exists (select 1 from voting_sessions where id = new.voting_session_id and status = 'CLOSED') then
            raise exception 'result_publications: a sessão de votação selecionada precisa estar CLOSED'
                using errcode = 'check_violation';
        end if;

        return new;
    end if;

    if new.event_id <> old.event_id or new.voting_session_id <> old.voting_session_id
        or new.version <> old.version or new.snapshot <> old.snapshot
        or new.published_by_user_id <> old.published_by_user_id or new.published_at <> old.published_at then
        raise exception 'result_publications: snapshot e dados da publicação são imutáveis'
            using errcode = 'check_violation';
    end if;

    if old.status = 'REVOKED' then
        raise exception 'result_publications: publicação revogada é definitiva'
            using errcode = 'check_violation';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION hacklab.technical_results_lock_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if tg_table_name = 'evaluations' and new.status is not distinct from old.status then
        return new;
    end if;

    if exists (select 1 from result_publications where event_id = new.event_id and status = 'PUBLISHED') then
        raise exception '%: resultado publicado; revogue a publicação antes de alterar o resultado técnico', tg_table_name
            using errcode = 'check_violation';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION hacklab.users_open_assignments_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if new.sector_id is not distinct from old.sector_id and new.status = old.status then
        return new;
    end if;

    if exists (
        select 1 from tasks t
        where t.assigned_user_id = new.id and t.status <> 'COMPLETED'
          and (new.status <> 'ACTIVE' or t.responsible_sector_id is distinct from new.sector_id)
    ) or exists (
        select 1 from occurrences o
        where o.assigned_user_id = new.id and o.status <> 'RESOLVED'
          and (new.status <> 'ACTIVE' or o.responsible_sector_id is distinct from new.sector_id)
    ) then
        raise exception 'users: usuário tem pendência/ocorrência aberta atribuída; reatribua antes de mudar setor ou inativar'
            using errcode = 'check_violation';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION hacklab.users_sector_matches_role()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    role_code text;
begin
    select code into role_code from roles where id = new.role_id;

    if role_code in ('MANAGER', 'EDITOR') and new.sector_id is null then
        raise exception 'Perfil % exige setor (users.sector_id).', role_code
            using errcode = 'check_violation';
    end if;

    if role_code not in ('MANAGER', 'EDITOR') and new.sector_id is not null then
        raise exception 'Perfil % não tem vínculo setorial (users.sector_id deve ser nulo).', role_code
            using errcode = 'check_violation';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION hacklab.voting_configuration_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    session_status text;
    target_session bigint;
begin
    if tg_op = 'UPDATE' then
        raise exception '%: registro não é alterado (retire e inclua)', tg_table_name
            using errcode = 'check_violation';
    end if;

    target_session := case when tg_op = 'DELETE' then old.voting_session_id else new.voting_session_id end;
    select status into session_status from voting_sessions where id = target_session for share;

    if session_status is distinct from 'DRAFT' then
        raise exception '%: configuração travada (sessão %)', tg_table_name, session_status
            using errcode = 'check_violation';
    end if;

    if tg_op = 'DELETE' then
        return old;
    end if;

    -- IFs aninhados: o PL/pgSQL não faz curto-circuito e new.team_id/new.user_id só existem numa tabela.
    if tg_table_name = 'voting_session_teams' then
        if not exists (select 1 from teams where id = new.team_id and status = 'ACTIVE') then
            raise exception 'voting_session_teams: equipe inativa não é candidata'
                using errcode = 'check_violation';
        end if;
    else
        if not exists (
            select 1 from users u join roles r on r.id = u.role_id
            where u.id = new.user_id and u.status = 'ACTIVE' and r.code = 'VOTER'
        ) then
            raise exception 'voting_eligibilities: só usuário ACTIVE com perfil VOTER'
                using errcode = 'check_violation';
        end if;
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION hacklab.voting_sessions_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if tg_op = 'DELETE' then
        raise exception 'voting_sessions: sessão não é apagada (cancele em DRAFT)'
            using errcode = 'check_violation';
    end if;

    if new.event_id <> old.event_id or new.created_by_user_id <> old.created_by_user_id then
        raise exception 'voting_sessions: evento e criador não mudam'
            using errcode = 'check_violation';
    end if;

    if old.status in ('CLOSED', 'CANCELLED') then
        raise exception 'voting_sessions: sessão % é definitiva', old.status
            using errcode = 'check_violation';
    end if;

    if old.opened_at is not null and new.opened_at is distinct from old.opened_at then
        raise exception 'voting_sessions: opened_at não muda'
            using errcode = 'check_violation';
    end if;

    if new.name <> old.name and old.status <> 'DRAFT' then
        raise exception 'voting_sessions: nome só muda em DRAFT'
            using errcode = 'check_violation';
    end if;

    if new.status <> old.status and not (
        (old.status = 'DRAFT' and new.status in ('OPEN', 'CANCELLED'))
        or (old.status = 'OPEN' and new.status in ('CLOSED', 'CANCELLED'))
    ) then
        raise exception 'voting_sessions: transição % -> % não permitida', old.status, new.status
            using errcode = 'check_violation';
    end if;

    if new.status = 'OPEN' and old.status = 'DRAFT' then
        if not exists (select 1 from voting_session_teams where voting_session_id = new.id)
            or not exists (select 1 from voting_eligibilities where voting_session_id = new.id) then
            raise exception 'voting_sessions: abrir exige candidatas e elegíveis'
                using errcode = 'check_violation';
        end if;
    end if;

    if new.status = 'CANCELLED' and exists (select 1 from public_votes where voting_session_id = new.id) then
        raise exception 'voting_sessions: sessão com votos não é cancelada'
            using errcode = 'check_violation';
    end if;

    return new;
end;
$function$
